 private static void renderPrepared(NativeSegmentedVisual visual,Motion motion,Object world,net.minecraft.core.BlockPos owner,PoseStack poses,MultiBufferSource buffers,int[] lights,int overlay,SegmentedGateContext context,double leftProgress,double rightProgress,boolean peers){var prepared=active;if(prepared==null||!visual.ready())return;double progress=visual.suppressed()||visual.awaitingChunk()?0:NativeSegmentedVisualClock.sample(world,owner,visual,motion,NativeSegmentedVisualClock.current());if(context==null){int steps=(visual.settings().direction<2?visual.height():visual.width())*motion.ticksPerSection()*6;progress=Math.round(progress*steps)/(double)steps;}renderAt(prepared.bake,visual,progress,poses,buffers,lights,overlay,context,peers?leftProgress:progress,peers?rightProgress:progress);}

