 public static net.minecraft.world.phys.AABB bounds(net.minecraft.core.BlockPos pos,NativeSegmentedVisual visual){var settings=visual.settings();if(settings.direction==0&&!settings.straight&&settings.position==0){double minX=-.01,maxX=1.01,minZ=.20,maxZ=visual.height()+1.01;switch(visual.facing()){case SOUTH:minZ=-visual.height()-.01;maxZ=.80;break;case WEST:minX=.20;maxX=visual.height()+1.01;minZ=-.01;maxZ=1.01;break;case EAST:minX=-visual.height()-.01;maxX=.80;minZ=-.01;maxZ=1.01;break;default:break;}return new net.minecraft.world.phys.AABB(pos.getX()+minX,pos.getY()+1-visual.height()-.01,pos.getZ()+minZ,pos.getX()+maxX,pos.getY()+1.51,pos.getZ()+maxZ);}double reach=(settings.direction<2?visual.height():visual.width())+1.01;return new net.minecraft.world.phys.AABB(pos.getX()-reach,pos.getY()-visual.height()-reach,pos.getZ()-reach,pos.getX()+reach+1,pos.getY()+reach+1,pos.getZ()+reach+1);}
